'use strict';
const flows={
  arc:{network:'ARC TESTNET · eip155:5042002',invoice:'Account snapshot',price:'0.011',unit:'test USDC',base:'0.010 resource price',markup:'+ 0.001 service markup',stages:[
    {glyph:'↗',label:'01 / REQUEST',title:'An agent asks.\nThe price is explicit.',description:'One Arc account snapshot, requested through MCP. A stable request key keeps a retry attached to the same intent.',evidence:'No payment is implied by a request or HTTP 402 response.',next:'Next: owner review'},
    {glyph:'◈',label:'02 / REVIEW',title:'The owner sees\nexactly what they approve.',description:'The buyer reviews an exact, expiring USDC payment authorization in MetaMask. The seller separately approves a proof bound to the settlement request.',evidence:'Both wallet actions are explicit in the current prototype. This illustration asks for neither.',next:'Next: verify settlement'},
    {glyph:'≋',label:'03 / VERIFY',title:'Verify the payment.\nThen release the work.',description:'The adapter checks the matching USDC transfer and authorization evidence on Arc testnet. Pending or uncertain settlement keeps the same request ID.',evidence:'Live owner-signed Arc settlement remains an outstanding project milestone.',next:'Next: agent receipt'},
    {glyph:'✓',label:'04 / RECEIVE',title:'A useful result.\nA matching receipt.',description:'After verified settlement, the agent can retrieve the account snapshot and payment receipt through MCP. This panel illustrates the intended completed flow; it is not a live receipt.',evidence:'The next phase connects both report services to this Arc USDC checkout rail.',next:'Replay the Arc flow'}]},
  mgas:{network:'BASE SEPOLIA FUNDING · SHARED SERVICE ACCOUNT',invoice:'Fee and slippage report',price:'0.055',unit:'MGAS credits',base:'0.050 base service price',markup:'+ 0.005 service markup',stages:[
    {glyph:'↗',label:'01 / REQUEST',title:'One funded account.\nA useful report.',description:'A verified Base tMGAS deposit credits one operator-managed prepaid account. The agent requests a report with frozen inputs and an explicit price cap.',evidence:'One deposited tMGAS becomes one service credit. Funding gas is separately reviewed.',next:'Next: owner review'},
    {glyph:'◈',label:'02 / REVIEW',title:'Approve the work.\nKnow the full charge.',description:'The owner reviews the service, input hash, network, exact price, nonce and expiry, then signs a bounded service-credit authorization in the browser.',evidence:'This is a local prepaid-credit purchase, not a token allowance or new on-chain transaction.',next:'Next: reserve and verify'},
    {glyph:'≋',label:'03 / VERIFY',title:'Reserve once.\nSettle on delivery.',description:'The ledger reserves the exact price and one worker runs the read-only service. Successful delivery settles once; failed or interrupted execution returns the reservation.',evidence:'Native service-execution gas is zero. Shared-credit native gas dispatch is disabled.',next:'Next: agent receipt'},
    {glyph:'✓',label:'04 / RECEIVE',title:'The agent gets\nthe work and its receipt.',description:'The same MCP job ID returns the calculated report and a matching operator-ledger charge receipt. Repeated polling does not purchase the report again.',evidence:'This service receipt is different from the blockchain receipt for the original deposit.',next:'Replay the MGAS flow'}]}
};
let rail='arc',step=0;
function renderFlow(){const data=flows[rail],stage=data.stages[step];document.getElementById('rail-network').textContent=data.network;document.getElementById('flow-glyph').textContent=stage.glyph;document.getElementById('flow-stage').textContent=stage.label;const title=document.getElementById('flow-title');title.replaceChildren();stage.title.split('\n').forEach((line,i)=>{if(i)title.append(document.createElement('br'));title.append(document.createTextNode(line));});document.getElementById('flow-description').textContent=stage.description;document.getElementById('flow-evidence').textContent=stage.evidence;document.getElementById('invoice-name').textContent=data.invoice;const price=document.getElementById('invoice-price');price.replaceChildren(document.createTextNode(data.price+' '));const unit=document.createElement('small');unit.textContent=data.unit;price.append(unit);document.getElementById('invoice-base').textContent=data.base;document.getElementById('invoice-markup').textContent=data.markup;const next=document.getElementById('flow-next');next.replaceChildren(document.createTextNode(stage.next+' '));const arrow=document.createElement('span');arrow.textContent=step===3?'↺':'→';next.append(arrow);document.getElementById('flow-counter').textContent=`${step+1} / 4`;document.querySelectorAll('[data-step]').forEach((li,i)=>{li.classList.toggle('active',i===step);li.classList.toggle('done',i<step)});document.querySelectorAll('[data-rail]').forEach(tab=>{const selected=tab.dataset.rail===rail;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1});document.getElementById('rail-panel').setAttribute('aria-labelledby',`${rail}-tab`)}
document.querySelectorAll('[data-rail]').forEach(tab=>{tab.addEventListener('click',()=>{rail=tab.dataset.rail;step=0;renderFlow()});tab.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key)){event.preventDefault();rail=event.key==='Home'?'arc':event.key==='End'?'mgas':rail==='arc'?'mgas':'arc';step=0;renderFlow();document.getElementById(`${rail}-tab`).focus()}})});
document.getElementById('flow-next')?.addEventListener('click',()=>{step=(step+1)%4;renderFlow()});document.getElementById('flow-reset')?.addEventListener('click',()=>{step=0;renderFlow()});
const menuButton=document.querySelector('.menu-toggle'),menu=document.getElementById('mobile-menu');menuButton?.addEventListener('click',()=>{const expanded=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(expanded));menuButton.setAttribute('aria-label',expanded?'Close navigation':'Open navigation');menu.hidden=!expanded});menu?.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{menu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open navigation')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu&&!menu.hidden){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.focus()}});
document.getElementById('copy-example')?.addEventListener('click',async()=>{const button=document.getElementById('copy-example'),status=document.getElementById('copy-status');const text='matex_gas_arc_request_payment({\n  payer: "<buyer public EVM address>",\n  maxAmountRaw: "11000",\n  requestKey: "arc_service_pilot_0001"\n})\n\n// After owner review and approval, poll the same ID.\nmatex_gas_arc_get_payment({ id: "<returned request id>" })';try{await navigator.clipboard.writeText(text);button.textContent='Copied ✓';status.textContent='MCP example copied.';}catch{button.textContent='Select code to copy';status.textContent='Clipboard access is unavailable. Select the example text and copy it manually.';}});
document.getElementById('print-brief')?.addEventListener('click',()=>window.print());
